package com.dy.artisan3d.diimport com.dy.artisan3d.data.repository.ArtisanAboutRepositoryImplimport com.dy.artisan3d.data.repository.ArtisanArticleRepositoryImplimport com.dy.artisan3d.data.repository.ArtisanArticleSingleRepositoryImplimport com.dy.artisan3d.data.repository.ArtisanMediaRepositoryImplimport com.dy.artisan3d.data.repository.BrandRepositoryImplimport com.dy.artisan3d.data.repository.CategoryRepositoryImplimport com.dy.artisan3d.data.repository.ProductDetailRepositoryImplimport com.dy.artisan3d.data.repository.ProductRepositoryImplimport com.dy.artisan3d.domain.repository.ArtisanAboutRepositoryimport com.dy.artisan3d.domain.repository.ArtisanArticleRepositoryimport com.dy.artisan3d.domain.repository.ArtisanArticleSingleRepositoryimport com.dy.artisan3d.domain.repository.ArtisanMediaRepositoryimport com.dy.artisan3d.domain.repository.BrandRepositoryimport com.dy.artisan3d.domain.repository.CategoryRepositoryimport com.dy.artisan3d.domain.repository.ProductDetailRepositoryimport com.dy.artisan3d.domain.repository.ProductRepositoryimport com.dy.artisan3d.ui.screen.main.about.AboutViewModelimport com.dy.artisan3d.ui.screen.main.article.detail.ArtisanArticleDetailViewModelimport com.dy.artisan3d.ui.screen.main.article.list.ArticleListViewModelimport com.dy.artisan3d.ui.screen.main.home.HomeViewModelimport com.dy.artisan3d.ui.screen.products.list.ProductListViewModelimport com.dy.artisan3d.ui.screen.products.view.ProductDetailViewModelimport io.ktor.client.HttpClientimport io.ktor.client.plugins.HttpTimeoutimport io.ktor.client.plugins.contentnegotiation.ContentNegotiationimport io.ktor.client.plugins.logging.LogLevelimport io.ktor.client.plugins.logging.Loggingimport io.ktor.serialization.kotlinx.json.jsonimport kotlinx.serialization.json.Jsonimport org.koin.core.KoinApplicationimport org.koin.core.context.startKoinimport org.koin.core.module.Moduleimport org.koin.core.module.dsl.viewModelimport org.koin.dsl.moduleexpect val targetModule: Modulefun initializeKoin(    config: (KoinApplication.() -> Unit)? = null,) {    startKoin {        config?.invoke(this)        modules(targetModule, navigationModule, networkModule)    }}val networkModule = module {    single {        HttpClient { // Platformaga qarab avtomatik tanlaydi (Android/Darwin)            install(ContentNegotiation) {                json(Json {                    ignoreUnknownKeys = true                    coerceInputValues = true // SHU QATORNI QO'SHING                    prettyPrint = true                })            }            install(Logging) {                level = LogLevel.ALL // Hamma request/response-ni logda ko'rsatadi            }            // Timeout-larni sozlash            install(HttpTimeout) {                requestTimeoutMillis = 15000            }        }    }    single<CategoryRepository> { CategoryRepositoryImpl(get()) }    single<ProductRepository> { ProductRepositoryImpl(get()) }    single<BrandRepository> { BrandRepositoryImpl(get()) }    single<ProductDetailRepository> { ProductDetailRepositoryImpl(get()) }    single<ArtisanMediaRepository> { ArtisanMediaRepositoryImpl(get()) }    single<ArtisanArticleRepository> { ArtisanArticleRepositoryImpl(get()) }    single<ArtisanArticleSingleRepository> { ArtisanArticleSingleRepositoryImpl(get()) }    single<ArtisanAboutRepository> { ArtisanAboutRepositoryImpl(get()) }    viewModel {        HomeViewModel(            repository = get(),            brandRepository = get(),            artisanMediaRepository = get(),            artisanArticleRepository = get(),            appLang = get()        )    }    // ProductListViewModel - parametrli    viewModel { params ->        ProductListViewModel(            repository = get(),            appLang = get(),            categoryId = params.values.getOrNull(0) as? Int, // 1-parametr            brandId = params.values.getOrNull(1) as? Int,    // 2-parametr            title = params.values.getOrNull(2) as? String ?: "" // 3-parametr        )    }    viewModel { params ->        ProductDetailViewModel(            repository = get(),            appLang = get(),            productId = params.values.getOrNull(0) as? Int ?: 0        )    }    viewModel {        ArticleListViewModel(            appLange = get(),            artisanArticleRepository = get()        )    }    viewModel { params ->        ArtisanArticleDetailViewModel(            artisanArticleSingleRepository = get(),            appLanguage = get(),            id = params.values.getOrNull(0) as? Int ?: 0        )    }    viewModel {        AboutViewModel(            aboutRepository = get(),            appLanguage = get()        )    }}